/// the low byte.
///
/// # Errors
///
/// Returns an I/O error if the read fails, and `UnexpectedEof` if fewer than
/// two bytes are available.
pub fn vtx_read_packet_id(file: &mut File) -> Result<u16, Error> {
    let mut buffer = [0u8; BUFFER_SIZE];
    let count = file.read(&mut buffer)?;
    if count < 2 {
